1	#!/usr/bin/env node
2	import { parseArgs } from 'node:util';
3	import { CYCLE, monthlyCents } from '../src/cycles.js';
4	import { parseDate, todayIso } from '../src/dates.js';
5	import { toCsv } from '../src/export.js';
6	import { formatEuros, parseEuros } from '../src/money.js';
7	import { upcoming } from '../src/renewals.js';
8	import { load, save, storePath, validate } from '../src/store.js';
9	
10	const USAGE = `usage: subtrack <command> [options]
11	
12	  add <name> <price> [--every month|year] [--since YYYY-MM-DD]
13	  list
14	  total
15	  renewals [--within <days>]
16	  export
17	  remove <name>
18	
19	options for every command: --file <path>, --today YYYY-MM-DD`;
20	
21	// how much of one charge falls in a month
22	const SHARE_PER_MONTH = { [CYCLE.MONTH]: 1, [CYCLE.YEAR]: 1 / 12 };
23	
24	function die(message, code = 1) {
25	  process.stderr.write(`subtrack: ${message}\n`);
26	  process.exit(code);
27	}
28	
29	// --every month|year (monthly/yearly work too)
30	const EVERY = { month: CYCLE.MONTH, monthly: CYCLE.MONTH, year: CYCLE.YEAR, yearly: CYCLE.YEAR };
31	
32	function cycleFlag(value = 'month') {
33	  const cycle = EVERY[value.toLowerCase()];
34	  if (!cycle) die(`--every must be month or year, got "${value}"`, 2);
35	  return cycle;
36	}
37	
38	let parsed;
39	try {
40	  parsed = parseArgs({
41	    args: process.argv.slice(2),
42	    allowPositionals: true,
43	    options: {
44	      every: { type: 'string' },
45	      since: { type: 'string' },
46	      within: { type: 'string' },
47	      today: { type: 'string' },
48	      file: { type: 'string' },
49	      help: { type: 'boolean', short: 'h' },
50	    },
51	  });
52	} catch (err) {
53	  die(`${err.message}\n\n${USAGE}`, 2);
54	}
55	const { values: opts, positionals } = parsed;
56	const [command, ...args] = positionals;
57	if (opts.help || !command) {
58	  console.log(USAGE);
59	  process.exit(command || opts.help ? 0 : 2);
60	}
61	
62	const file = storePath(opts.file);
63	const today = opts.today === undefined ? todayIso() : parseDate(opts.today);
64	if (today === null) die(`--today must be a date (YYYY-MM-DD), got "${opts.today}"`, 2);
65	
66	let subs;
67	try {
68	  subs = load(file);
69	} catch (err) {
70	  die(err.message);
71	}
72	
73	switch (command) {
74	  case 'add': {
75	    const [name, priceText] = args;
76	    if (!name || priceText === undefined) die(`add needs a name and a price\n\n${USAGE}`, 2);
77	    const price = parseEuros(priceText);
78	    if (price === null) die(`"${priceText}" is not a price (try 12.99)`, 2);
79	    const since = opts.since === undefined ? today : parseDate(opts.since);
80	    if (since === null) die(`--since must be a date (YYYY-MM-DD), got "${opts.since}"`, 2);
81	    if (subs.some((s) => s.name.toLowerCase() === name.toLowerCase())) die(`${name} is already on the list`);
82	    const sub = { name, price, cycle: cycleFlag(opts.every), since };
83	    const problem = validate(sub);
84	    if (problem) die(problem, 2);
85	    subs.push(sub);
86	    save(file, subs);
87	    console.log(`Added ${name}: ${formatEuros(price)} ${sub.cycle}, ${formatEuros(monthlyCents(sub))} a month.`);
88	    break;
89	  }
90	  case 'list': {
91	    if (!subs.length) {
92	      console.log('No subscriptions yet. Add one with: subtrack add <name> <price>');
93	      break;
94	    }
95	    const width = Math.max(...subs.map((s) => s.name.length));
96	    for (const s of subs) {
97	      console.log(`${s.name.padEnd(width)}  ${formatEuros(s.price).padStart(10)} ${s.cycle.padEnd(8)} ${formatEuros(monthlyCents(s)).padStart(10)} a month`);
98	    }
99	    break;
100	  }
101	  case 'total': {
102	    // add up the exact amounts and cut to the cent once, so cut-off cents don't pile up across plans
103	    const total = Math.floor(subs.reduce((sum, s) => sum + s.price * (SHARE_PER_MONTH[s.cycle] ?? 0), 0) + 1e-9);
104	    console.log(`Monthly total: ${formatEuros(total)} (${subs.length} ${subs.length === 1 ? 'plan' : 'plans'})`);
105	    break;
106	  }
107	  case 'renewals': {
108	    const within = opts.within === undefined ? 30 : Number(opts.within);
109	    if (!Number.isInteger(within) || within < 0) die(`--within must be a whole number of days, got "${opts.within}"`, 2);
110	    const rows = upcoming(subs, today, within);
111	    if (!rows.length) {
112	      console.log(`Nothing renews in the next ${within} days.`);
113	      break;
114	    }
115	    const width = Math.max(...rows.map((r) => r.name.length));
116	    for (const r of rows) {
117	      console.log(`${r.when.padEnd(6)}  ${r.name.padEnd(width)}  ${formatEuros(r.price)}`);
118	    }
119	    break;
120	  }
121	  case 'export':
122	    process.stdout.write(toCsv(subs, today));
123	    break;
124	  case 'remove': {
125	    const [name] = args;
126	    const left = subs.filter((s) => s.name.toLowerCase() !== String(name).toLowerCase());
127	    if (left.length === subs.length) die(`${name} is not on the list`);
128	    save(file, left);
129	    console.log(`Removed ${name}.`);
130	    break;
131	  }
132	  default:
133	    die(`unknown command "${command}"\n\n${USAGE}`, 2);
134	}
135

